const settings = $('Campaign Settings').first().json;
const response = $input.first().json;
const tweets = Array.isArray(response.tweets) ? response.tweets : [];
const asCount = (value) => {
  const count = Number(value ?? 0);
  return Number.isFinite(count) ? count : 0;
};
const minimumLikes = asCount(settings.minimumLikes);

const qualified = tweets
  .filter((tweet) => {
    const username = tweet.author?.username;
    return (
      typeof tweet.id === 'string' &&
      typeof tweet.text === 'string' &&
      tweet.text.trim().length > 0 &&
      typeof username === 'string' &&
      username.length > 0 &&
      asCount(tweet.likeCount) >= minimumLikes
    );
  })
  .map((tweet) => {
    const likes = asCount(tweet.likeCount);
    const reposts = asCount(tweet.retweetCount);
    const replies = asCount(tweet.replyCount);
    const quotes = asCount(tweet.quoteCount);
    return {
      id: tweet.id,
      text: tweet.text.trim(),
      author: tweet.author.name ?? tweet.author.username,
      username: tweet.author.username,
      createdAt: tweet.createdAt ?? null,
      likes,
      reposts,
      replies,
      quotes,
      engagement: likes + reposts + replies + quotes,
      url: `https://x.com/${tweet.author.username}/status/${tweet.id}`,
    };
  })
  .sort((left, right) => right.engagement - left.engagement);

if (qualified.length === 0) {
  return [{
    json: {
      resultType: 'diagnostic',
      status: 'no_qualified_mentions',
      query: settings.campaignQuery,
      returnedTweets: tweets.length,
      message: 'No posts met the current campaign filters.',
    },
  }];
}

const engagementTotals = qualified.reduce(
  (totals, mention) => ({
    likes: totals.likes + mention.likes,
    reposts: totals.reposts + mention.reposts,
    replies: totals.replies + mention.replies,
    quotes: totals.quotes + mention.quotes,
  }),
  { likes: 0, reposts: 0, replies: 0, quotes: 0 },
);

return [{
  json: {
    resultType: 'campaign_brief',
    query: settings.campaignQuery,
    returnedTweets: tweets.length,
    qualifiedMentions: qualified.length,
    engagementTotals,
    topMentions: qualified.slice(0, 10),
  },
}];
